const soundscape=new Soundscape();
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const reviewAccess=createReviewAccess();
const purchases=createPurchases({bridge:globalThis.GlimbraidStore,reviewAccess});let wantedPaidLevel=null;
watchLayout(root,modal);
const KEY=reviewAccess.progressKey;let storageOK=true,saved;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{saved={};storageOK=false;}
let data={version:1,lang: resolveLanguage(navigator.language),sound:true,ambience:false,haptics:true,showTime:true,records:{},completed:[],last:1,...saved};
delete data.profiles;delete data.activeProfile;
let profiles=Array.isArray(saved.profiles)&&saved.profiles.length?saved.profiles.slice(0,6):[{id:'first',name:translator(data.lang)('defaultPlayer',{n:1}),autoName:true,symbol:0,data:{...data}}];
let activeProfile=profiles.find(p=>p.id===saved.activeProfile)||profiles[0];data={...data,...activeProfile.data};
let scoreMetric='time',scoreLevel=1,scoreScope='level',scoreChapter='night',pendingDelete=null,pendingBackup=null,dialogStack=[],profileDraft=null,levelView='journey',previousBest=null,lastCheckpoint=0,toast='';
const avatarColors=['#95f4c9','#ffc77a','#aebeff','#ffb8de','#94e6ff','#ffe79c'];
const symbols=['✦','◇','☾','✿','❖','☀'];
data.lang=resolveLanguage(data.lang);if(!Array.isArray(data.completed))data.completed=[];data.completed=data.completed.filter(n=>Number.isInteger(n)&&n>=1&&n<=levels.length);if(!data.records||typeof data.records!=='object')data.records={};
profiles.forEach(p=>initHints(p.data));initHints(data);
for(const p of profiles)if(!canWear(p.data,p.hat||'none'))p.hat='none';
let bankAward=0,chapterReward=null,cardReady=null,cardGeneration=0,cardSnapshot=null,cardSending=false;
let t=translator(data.lang),screen='home',level,rot=[],history=[],moves=0,assisted=false,started=false,elapsed=0,lastTick=0,paused=false,won=false,dialogType='',resultRecord=false,pendingHint=null,hintsUsed=0,practice=false,selectedChapter='night';
const fmt=ms=>{const s=Math.floor(ms/1000);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
function snapshotAttempt(){if(screen==='play'&&level&&!won)data.attempt={level:level.id,rot:[...rot],history:history.slice(-1000).map(r=>[...r]),moves,elapsed,assisted,started,pendingHint,hintsUsed,practice};}
function persist(){syncDefaultNames(profiles,data.lang);snapshotAttempt();try{activeProfile.data={...data};localStorage.setItem(KEY,JSON.stringify({...data,version:2,activeProfile:activeProfile.id,profiles}));}catch{storageOK=false;}}
function tick(force=false){if(started&&!paused&&!won&&screen==='play'&&(!document.hidden||force)){const now=performance.now();if(lastTick)elapsed+=now-lastTick;lastTick=now;}else lastTick=0;if(screen==='play'&&!won&&performance.now()-lastCheckpoint>1000){lastCheckpoint=performance.now();persist();}const clock=document.querySelector('#clock');if(clock)clock.textContent=fmt(elapsed);}
globalThis.addEventListener?.('pagehide',()=>{tick(true);persist();});
setInterval(tick,100);document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='play'&&!won){tick(true);pause();}lastTick=0;syncAmbience();});
function sound(kind='rotate'){soundscape.play(kind,data.sound,chapterFor(level?.id||continueLevel()).id);}
let nativeBackgrounded=false;
function currentChapter(){return screen==='levels'?chapters.find(c=>c.id===selectedChapter):chapterFor(screen==='play'?level?.id:continueLevel());}
function syncAmbience(){soundscape.ambient(data.ambience&&!paused&&!document.hidden&&!nativeBackgrounded,currentChapter()?.id);}
globalThis.addEventListener?.('sporlys:native-state',event=>{nativeBackgrounded=!event.detail.isActive;if(nativeBackgrounded){tick(true);if(screen==='play'&&!won&&!paused)pause();persist();}lastTick=0;syncAmbience();});
globalThis.addEventListener?.('sporlys:native-back',event=>{tick(true);persist();if(modal.open){event.preventDefault();if(dialogStack.length)action('dialogBack');else closeDialog();}else if(screen==='play'){event.preventDefault();if(won)action('home');else pause();}else if(screen!=='home'){event.preventDefault();action('home');}});
function animateMove(before,i,turns=1){
 const after=evaluate(level,rot),reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 if(!reduced){const track=document.querySelector(`[data-rotate="${i}"] .tracks`);track?.animate?.([{transform:`rotate(${-90*turns}deg)`},{transform:'rotate(0deg)'}],{duration:180,easing:'cubic-bezier(.2,.8,.2,1)'});
 after.lit.forEach((groups,j)=>groups.forEach((colors,g)=>{const group=document.querySelector(`[data-rotate="${j}"] [data-track="${g}"]`);if([...colors].some(c=>!before.lit[j][g].has(c)))group?.classList.add('new-connection');if(!colors.size&&before.lit[j][g].size&&group){const path=group.querySelector('.channel')?.cloneNode();if(path){path.setAttribute('class','fading-track');path.setAttribute('stroke',({amber:'#ffc77a',violet:'#cab1ff',mint:'#95f4c9'})[[...before.lit[j][g]][0]]);group.append(path);const animation=path.animate([{opacity:.75},{opacity:0}],{duration:140,fill:'forwards'});animation.finished.then(()=>path.remove()).catch(()=>path.remove());}}}));
 after.targets.forEach(target=>{if(target.lit&&!before.targets.find(x=>x.i===target.i)?.lit){document.querySelector(`[data-rotate="${target.i}"]`)?.classList.add('beacon-lit');document.querySelector(`[data-beacon="${target.i}"]`)?.classList.add('just-awakened');}});}
 if(after.open&&!before.open)document.querySelector(`[data-rotate="${level.gate.tile}"]`)?.classList.add('port-opened');
 if(!won)document.querySelector(`[data-rotate="${i}"]`)?.focus?.({preventScroll:true});
 if(!won){if(after.open&&!before.open){sound('gate');}else if(after.targets.some(t=>t.lit&&!before.targets.find(x=>x.i===t.i)?.lit))sound('beacon');}
}
function world(){document.querySelector('.world-lights').innerHTML=Array.from({length:levels.length},(_,i)=>`<i style="--x:${10+i*(80/(levels.length-1))}%;--y:${83-(i%3)*3}%;opacity:${data.completed.includes(i+1)?1:0}"></i>`).join('');}
function nodeShape(color,fill,stroke){return color==='violet'?`<path d="M50 38 L62 59 L38 59 Z" fill="${fill}" stroke="${stroke}" class="node" style="color:${stroke}"/>`:color==='amber'?`<rect x="42" y="42" width="16" height="16" rx="3" transform="rotate(45 50 50)" fill="${fill}" stroke="${stroke}" class="node" style="color:${stroke}"/>`:`<circle cx="50" cy="50" r="10" fill="${fill}" stroke="${stroke}" class="node" style="color:${stroke}"/>`;}
function tileSvg(l,r,i,state){const tile=l.tiles[i],colors={violet:'#cab1ff',mint:l.frozen!==undefined?'#a9ebff':'#95f4c9',amber:'#ffc77a'};let drawing='<g class="tracks">';tile.groups.forEach((group,g)=>{const coords=[[50,0],[100,50],[50,100],[0,50]],ps=ports(l,r,i,g);let path;if(ps.length===1){const [x,y]=coords[ps[0]];path=`M50 50 L${x} ${y}`;}else if(ps.length===2){const a=coords[ps[0]],b=coords[ps[1]];path=ps[0]%2===ps[1]%2?`M${a[0]} ${a[1]} L${b[0]} ${b[1]}`:`M${a[0]} ${a[1]} Q50 50 ${b[0]} ${b[1]}`;}else{path=ps.map(p=>`M50 50 L${coords[p][0]} ${coords[p][1]}`).join(' ');}const lit=[...state.lit[i][g]],color=lit.length>1?'#e3f1ca':colors[lit[0]];drawing+=`<g data-track="${g}"><path d="${path}" class="rim"/><path d="${path}" class="channel"/><path d="${path}" class="unlit-track"/>${color?`<path d="${path}" class="light-halo" style="stroke:${color}"/><path d="${path}" class="flow" style="stroke:${color};color:${color}"/><path d="${path}" class="light-core"/><path d="${path}" pathLength="100" class="light-surge"/>`:''}</g>`;});
 drawing+='</g>';for(const key of ['source','target']){const node=tile[key];if(!node)continue;const on=state.lit[i][node.group].has(node.color);drawing+=`<g class="node-fitting ${key} ${on?'on':''}" style="color:${colors[node.color]}">${key==='source'?'<path d="M50 28 L69 39 L69 61 L50 72 L31 61 L31 39 Z" class="source-casing"/>':'<circle cx="50" cy="50" r="22" class="target-casing"/><circle cx="50" cy="50" r="26" class="target-wave"/>'}</g>`;drawing+=`${on?`<circle cx="50" cy="50" r="22" fill="${colors[node.color]}" class="node-aura"/>`:""}<circle cx="50" cy="50" r="17" fill="#0a1925" stroke="${colors[node.color]}" opacity=".9"/>`+nodeShape(node.color,on?colors[node.color]:'#152a39',colors[node.color]);if(key==='source')drawing+='<circle cx="50" cy="50" r="3" fill="#fff6de"/>';}
 if(l.frozen===i&&!state.open)drawing+='<g class="ice-lock"><path d="M50 15v70M20 32l60 36M20 68l60-36M44 20l6 7 6-7M44 80l6-7 6 7"/></g>';
 if(tile.gate)drawing+=`<g class="gate-fitting ${state.open?'open':''}"><rect x="30" y="36" width="40" height="28" rx="5" class="gate-casing"/><path d="M43 38 L43 62 M50 38 L50 62 M57 38 L57 62" class="gate-bars"/><rect x="44" y="44" width="12" height="12" rx="2" transform="rotate(45 50 50)" class="gate-key"/></g>`;
 if(tile.groups.length>1)drawing+='<circle cx="87" cy="87" r="3" fill="#b8ccda"/><circle cx="78" cy="87" r="3" fill="#b8ccda"/>';
 return `<svg viewBox="0 0 100 100" aria-hidden="true">${drawing}</svg>`;}
function board(l,r,interactive=true){const state=evaluate(l,r);return `<div class="board ${state.solved?'solved':''} size-${l.n}" data-chapter="${chapterFor(l.id).id}" style="--n:${l.n}" ${interactive?'role="group"':''} aria-label="${t('level')} ${l.id}">${l.tiles.map((tile,i)=>{let label=t('tile',{n:i+1});if(tile.groups.length>1)label+=`, ${t('double')}`;if(tile.source)label+=`, ${t('source')}, ${t(tile.source.color)}`;if(tile.target)label+=`, ${t('target')}, ${t(tile.target.color)}`;if(tile.gate)label+=`, ${t('gate')}`;if(l.frozen===i&&!state.open)label+=`, ${t('frozen')}`;return `<${interactive?'button':'div'} style="--stone-x:${(i%3)*35}%;--stone-y:${(i%4)*25}%" class="tile ${l.frozen===i&&!state.open?'frozen-tile':''} ${interactive&&pendingHint?.tile===i?'hint-selected':''} ${state.lit[i].some(g=>g.size)?"energized":""} ${tile.source?.color||""}" ${interactive?`data-rotate="${i}" aria-label="${label}" ${won||paused||(l.frozen===i&&!state.open)?'disabled':''}`:''}>${tileSvg(l,r,i,state)}</${interactive?'button':'div'}>`;}).join('')}</div>`;}
function beacons(state){return `<div class="target-strip" role="status" aria-label="${t('lit',{a:state.targets.filter(x=>x.lit).length,b:state.targets.length})}">${state.targets.map(target=>`<span data-beacon="${target.i}" class="hud-beacon ${target.color} ${target.lit?'awake':''}" aria-hidden="true"><svg viewBox="0 0 24 24" aria-hidden="true">${target.color==='violet'?'<path d="M12 3 22 21H2Z"/>':target.color==='amber'?'<path d="m12 2 10 10-10 10L2 12Z"/>':'<circle cx="12" cy="12" r="9"/>'}</svg></span>`).join('')}<span class="sr-only">${t('lit',{a:state.targets.filter(x=>x.lit).length,b:state.targets.length})}</span></div>`;}
function journey(chapter){const series=levels.filter(l=>l.id>=chapter.start&&l.id<=chapter.end);const points=series.map((l,i)=>({x:i%2?62:38,y:(50+i*80)/(series.length*80+20)*100}));let path='',segments='';for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],d=`M${a.x} ${a.y} C${a.x} ${a.y+8} ${b.x} ${b.y-8} ${b.x} ${b.y}`;path+=d;segments+=`<path d="${d}" class="journey-link ${data.completed.includes(series[i-1].id)?'lit':''}"/>`;}
 return `<div class="journey-map" style="height:${series.length*80+20}px"><svg class="journey-path" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="${path}" class="journey-shadow"/>${segments}</svg>${series.map((l,i)=>{const complete=data.completed.includes(l.id),available=levelUnlocked(l.id),record=data.records[l.id],point=points[i];return `<div class="journey-stop ${i%2?'left-label':'right-label'}" style="--x:${point.x}%;--y:${point.y}%"><button class="journey-node ${complete?'completed':available?'next-stop':'locked-stop'}" data-level="${l.id}" ${available?'':'disabled'} aria-label="${t('level')} ${l.id}, ${t(complete?'finished':available?'levelReady':'locked')}"><span>${String(l.id).padStart(2,'0')}</span>${complete?'<small aria-hidden="true">✦</small>':''}</button><div class="journey-label"><strong>${t('level')} ${l.id}</strong><span>${t(complete?'finished':available?'next':'locked')}</span>${record?`<small>${fmt(record.time)} · ${record.moves} ${t('moves').toLowerCase()}</small>`:''}</div></div>`;}).join('')}</div>`;
}
function chapterPreview(){return `<section class="chapter-preview"><span class="chapter-orb" aria-hidden="true">◇</span><div><span class="eyebrow">${t('finalJourney')}</span><h3>${t('allWorlds')}</h3><p>${t('finalJourneyNote')}</p></div></section>`;}
function header(title,right=''){return `<div class="topbar"><button class="icon" data-action="home" aria-label="${t('back')}">${icon('back')}</button><span class="eyebrow">${title}</span>${right||'<span style="width:48px"></span>'}</div>`;}
function continueLevel(){const a=validAttempt(data.attempt,levels,data.completed,reviewAccess.active);if(a)return a.level;return levels.find(l=>!data.completed.includes(l.id))?.id||Math.min(levels.length,Math.max(1,Number(data.last)||1));}
let renderedScreen='';
function render(){const screenChanged=renderedScreen!==screen;syncAmbience();t=translator(data.lang);document.documentElement.lang=data.lang;const description=document.querySelector('meta[name="description"]');description?.setAttribute?.('content',t('metaDescription'));document.documentElement.classList?.toggle('game-playing',screen==='play');root.classList.toggle('playing',screen==='play');root.classList.toggle('home-screen',screen==='home');const current=screen==='play'?chapterFor(level?.id):screen==='levels'?chapters.find(c=>c.id===selectedChapter):chapterFor(continueLevel());document.documentElement.classList?.toggle('forest-theme',current.id==='forest');document.documentElement.classList?.toggle('frost-theme',current.id==='frost');document.documentElement.classList?.toggle('rav-theme',current.id==='rav');document.documentElement.classList?.toggle('aurora-theme',current.id==='aurora');document.documentElement.classList?.toggle('stellar-theme',current.id==='stellar');document.documentElement.classList?.toggle('solar-theme',current.id==='solar');document.documentElement.classList?.toggle('weave-theme',current.id==='weave');world();if(screen==='home'){const resume=!!validAttempt(data.attempt,levels,data.completed,reviewAccess.active)||data.completed.length>0,next=continueLevel(),complete=data.completed.length===levels.length;root.innerHTML=`<section class="home"><div class="home-topbar"><button class="player-chip" style="--avatar:${avatarColors[activeProfile.symbol]}" data-action="players"><span class="chip-avatar">${avatarHTML(activeProfile)}</span><span>${escapeHtml(activeProfile.name)}</span></button><button class="icon" data-action="settings" aria-label="${t('settings')}">${icon('settings')}</button></div><div class="home-brand"><img class="brand-icon" src="icon-512.png" width="128" height="128" alt=""><h1 class="brand glimbraid-brand"><img src="glimbraid-wordmark.svg" alt="Glimbraid"></h1><p class="tagline">${t('tagline')}</p></div><button class="primary home-play" data-action="start"><span>${t(validAttempt(data.attempt,levels,data.completed,reviewAccess.active)?'continue':complete?'again':resume?'continue':'play')}</span><small>${t('level')} ${next}</small></button><button class="home-levels" data-action="levels">${t('levels')}</button><div class="home-progress panel"><div class="progress-caption"><strong>${t(current.key)}</strong><span>${t('progressShort',{a:data.completed.filter(id=>id>=current.start&&id<=current.end).length,b:current.end-current.start+1})}</span></div><div class="progress-track" role="img" aria-label="${t('journey',{a:data.completed.filter(id=>id>=current.start&&id<=current.end).length,b:current.end-current.start+1})}">${levels.filter(l=>l.id>=current.start&&l.id<=current.end).map(l=>`<span class="${data.completed.includes(l.id)?'done':''}"></span>`).join('')}</div></div><div class="hint-bank-home"><strong>${t('hintBank',{n:data.hintBalance})}</strong><p>${t('bankIntro')}</p><p>${t('bankCapacity',{n:bankLimit(data)})}</p></div><footer class="home-footer"><div class="foot-actions"><button class="text-button" data-action="scores">${t('scores')}</button><button class="text-button" data-action="help">${t('help')}</button><button class="text-button" data-action="about">${t('about')}</button></div><div class="foot">${t(storageOK?'local':'storageError')}</div>${toast?`<p role="status" class="toast">${toast}</p>`:''}</footer></section>`;}
 else if(screen==='levels'){root.innerHTML=header(t('levels'))+`<div class="chapter-tabs" role="group" aria-label="${t('chooseChapter')}">${chapters.map(c=>`<button data-chapter="${c.id}" class="${c.id===current.id?'selected':''}" aria-pressed="${c.id===current.id}" ${!levelUnlocked(c.start)&&purchases.canPlay(c.start)?'disabled':''}>${t(c.key)}${!purchases.canPlay(c.start)||!levelUnlocked(c.start)?' · ◇':''}</button>`).join('')}</div><div class="journey-heading"><div class="eyebrow">${t(current.series)}</div><h2>${t(current.key)}</h2><p class="muted">${t('journey',{a:data.completed.filter(id=>id>=current.start&&id<=current.end).length,b:current.end-current.start+1})}</p></div><div class="view-switch">${['journey','grid'].map(v=>`<button data-view="${v}" aria-pressed="${levelView===v}">${t(v==='grid'?'overview':'journeyView')}</button>`).join('')}</div>${earnedHeadwear(data).includes(current.id)?`<button class="chapter-share-button" data-action="chapterCard">${t('chapterCard')}</button>`:''}${levelView==='grid'?levelGrid(current):journey(current)}${current.id===chapters.at(-1).id?chapterPreview():''}`;}
 else if(screen==='play'){const state=evaluate(level,rot),tip={intro:'intro',route:'route',double:'doubleTip',colors:'colors',gate:'gateTip',threeColors:'threeColors'}[level.kind],record=data.records[level.id];root.innerHTML=`<section class="play ${won?'victory':''}">${header(`${t(current.key)} · ${t('level')} ${level.id}`,`<button class="icon" data-action="pause" aria-label="${t('pause')}">${icon('pause')}</button>`)}<div class="playing-player" style="--avatar:${avatarColors[activeProfile.symbol]}">${avatarHTML(activeProfile)} ${escapeHtml(activeProfile.name)}</div>${won?`<h2 role="status">${t('levelClear')}</h2>`:level.id<=2?`<p class="mission-caption">${t('goal')}</p>`:''}<div class="stats">${beacons(state)}<span>${t('moves')}<strong>${moves}</strong></span>${data.showTime?`<span>${t('time')}<strong id="clock">${fmt(elapsed)}</strong></span>`:''}</div><div class="board-wrap">${board(level,rot)}</div><p class="instructions"><span class="instruction-full">${t(won?'victoryDetail':pendingHint?(practice?'practiceHintMarked':'hintMarked'):level.id===63||level.id===64?'largeBoardTip':level.paths.some(p=>p.color==='violet')?(level.frozen!==undefined?'ravFrozenTip':level.gate?'ravGateTip':'threeColors'):current.id==='frost'?'frostTip':tip)}</span><span class="instruction-compact">${t(won?'victoryDetail':pendingHint?'compactHint':level.frozen!==undefined?'compactFrost':level.gate?'compactGate':'compactTip')}</span>${practice&&!won?` <span class="practice-badge">${t('practice')}</span>`:''}</p>${won?`<button class="primary victory-continue" data-action="result">${t('seeResult')}</button>`:`<div class="controls round-controls"><button data-action="undo" aria-label="${t('undo')}" ${!history.length||won?'disabled':''}><span class="control-orb" aria-hidden="true">${icon('undo')}</span><span>${t('undo')}</span></button><button data-action="hint" aria-label="${pendingHint?t('applyHint'):practice?t('hint'):remainingHints(data,level.id,hintsUsed)===0?t('practice'):t('hintsRemaining',{n:remainingHints(data,level.id,hintsUsed)})}" ${won?'disabled':''}><span class="control-orb" aria-hidden="true">${icon('hint')}<small class="hint-count">${practice?'∞':remainingHints(data,level.id,hintsUsed)}</small></span><span>${t(pendingHint?'applyHint':!practice&&remainingHints(data,level.id,hintsUsed)===0?'practiceShort':'hint')}</span></button><button data-action="restart" aria-label="${t('restart')}"><span class="control-orb" aria-hidden="true">${icon('restart')}</span><span>${t('restartShort')}</span></button><button data-action="help" aria-label="${t('help')}"><span class="control-orb" aria-hidden="true">${icon('help')}</span><span>${t('help')}</span></button></div>`}${!won?`<p class="hint-budget">${t('hintBudget',{a:basicHints(data,level.id,hintsUsed),b:data.hintBalance})}</p>`:''}${record?`<p class="best-line">${t('best')}: ${fmt(record.time)} · ${t('fewest')}: ${record.moves}</p>`:''}</section>`;}if(reviewAccess.active)root.innerHTML=`<div class="review-banner" role="status">${t('reviewActive')}</div>`+root.innerHTML;if(screenChanged){globalThis.scrollTo?.(0,0);if(document.scrollingElement)document.scrollingElement.scrollTop=0;renderedScreen=screen;}}
function levelUnlocked(id){return reviewAccess.active||id===1||data.completed.includes(id-1);}
function start(id,resume=false){if(!Number.isInteger(id)||id<1||id>levels.length)throw new Error('Invalid level');if(!levelUnlocked(id))throw new Error('Level locked');if(!purchases.canPlay(id)){wantedPaidLevel=id;showDialog('purchase');return;}bankAward=0;chapterReward=null;level=levels[id-1];rot=[...level.initial];history=[];moves=0;elapsed=0;started=false;lastTick=0;assisted=false;paused=false;won=false;resultRecord=false;pendingHint=null;hintsUsed=0;practice=false;screen='play';data.last=id;previousBest=data.records[id]?{...data.records[id]}:null;const a=resume?validAttempt(data.attempt,levels,data.completed,reviewAccess.active):null;if(a&&a.level===id){rot=a.rot;history=a.history;moves=a.moves;elapsed=a.elapsed;assisted=a.assisted;started=a.started;pendingHint=a.pendingHint;hintsUsed=a.hintsUsed;practice=a.practice;}dialogStack=[];persist();closeDialog();render();}
function begin(){if(!started){started=true;lastTick=performance.now();}}
function rotate(i){if(screen!=='play'||paused||won||!Number.isInteger(i)||i<0||i>=rot.length)throw new Error('Rotation unavailable');const before=evaluate(level,rot);if(level.frozen===i&&!before.open)return;pendingHint=null;begin();tick();history.push([...rot]);rot[i]=(rot[i]+1)%4;moves++;sound();if(data.haptics)try{navigator.vibrate?.(8);}catch{}render();checkWin();animateMove(before,i);}
function checkWin(){if(!evaluate(level,rot).solved){persist();return;}tick();won=true;delete data.attempt;lastTick=0;const previousHats=earnedHeadwear(data);bankAward=bankOnCompletion(data,level.id);chapterReward=earnedHeadwear(data).find(h=>!previousHats.includes(h))||null;const result=recordResult(data.records[level.id],elapsed,moves,assisted);if(result.record)data.records[level.id]=result.record;resultRecord=result.improved;persist();render();sound('victory');}
function pause(){if(won||screen!=='play')return;tick();paused=true;lastTick=0;persist();showDialog('pause');render();}
function closeDialog(){wantedPaidLevel=null;dialogStack=[];profileDraft=null;cardGeneration++;cardReady=null;cardSnapshot=null;if(modal.open)modal.close();dialogType='';if(screen==='play'&&!won){paused=false;lastTick=0;}render();}
function showDialog(type,record=resultRecord){tick();paused=screen==='play'&&!won;lastTick=0;dialogType=type;modal.className=type==='result'?'result-dialog':['players','newPlayer','editPlayer','chapterCard'].includes(type)?'players-dialog':'';let html='';if(type==='settings')html=`<h2>${t('settings')}</h2><div class="dialog-actions"><button data-action="players">${t('players')}</button><button data-action="scores">${t('scores')}</button><button data-action="backup">${t('backup')}</button><button data-action="purchase">${t(purchases.state.owned?'fullGameActive':'fullGameTitle')}</button></div><label class="setting">${t('language')}<select id="language">${languages.map(l=>`<option value="${l.code}" lang="${l.code}" ${data.lang===l.code?'selected':''}>${l.name}</option>`).join('')}</select></label><label class="setting">${t('sound')}<input type="checkbox" id="sound" ${data.sound?'checked':''}></label><label class="setting">${t('ambience')}<input type="checkbox" id="ambience" ${data.ambience?'checked':''}></label><label class="setting">${t('haptics')}<input type="checkbox" id="haptics" ${data.haptics?'checked':''}></label><label class="setting">${t('showTime')}<input type="checkbox" id="showTime" ${data.showTime?'checked':''}></label><button class="menu-return" data-action="reviewAccess">${t(reviewAccess.active?'reviewEnd':'reviewTitle')}</button><p>${t(storageOK?'local':'storageError')}</p><img class="studio-logo" src="bjerkholt-studio-logo.png" alt="Bjerkholt Studio">`;
 if(type==='reviewAccess')html=reviewView();
 if(type==='purchase')html=purchaseView();
 if(type==='chapterCard')html=`<h2>${t('chapterCard')}</h2><div id="chapterCardPreview" class="chapter-card-preview" role="status">${t('cardPreparing')}</div><div class="card-actions"><button class="primary" data-action="shareChapterCard" disabled>${t('shareCard')}</button><button data-action="saveChapterCard" disabled>${t('saveCard')}</button></div><p id="cardStatus" role="status"></p>`;
 if(type==='backup')html=backupView();
 if(type==='deletePlayerConfirm'&&pendingDelete){const p=profiles.find(p=>p.id===pendingDelete);if(p)html=`<h2>${escapeHtml(t('deletePlayerTitle',{name:p.name}))}</h2><p>${t('deletePlayerWarning')}</p>${profiles.length===1?`<p>${t('deleteLastPlayer')}</p>`:''}<button class="primary" data-action="cancelDeletePlayer" autofocus>${t('cancel')}</button><button class="danger-button" data-action="confirmDeletePlayer">${t('deletePlayer')}</button>`;}if(type==='players')html=playersView();if(type==='newPlayer'||type==='editPlayer')html=profileForm(type==='newPlayer');
 if(type==='scores')html=scoresView();
 if(type==='practice')html=`<h2>${t('practice')}</h2><p>${t('practiceExplain')}</p><button class="primary" data-action="enterPractice">${t('enterPractice')}</button><button class="result-home" data-action="close">${t('keepPlaying')}</button>`;
 if(type==='about')html=`<img class="about-icon" src="icon-192.png" width="80" height="80" alt="Glimbraid"><h2>${t('about')}</h2><p>${t('aboutDesc')}</p><img class="studio-logo" src="bjerkholt-studio-logo.png" alt="Bjerkholt Studio"><p>${t('aboutStorage')}</p><a class="info-link" href="privacy.html?lang=${encodeURIComponent(data.lang)}" target="_blank" rel="noopener">${t('privacyOpen')}</a><p>${t('contact')}:<br><a href="mailto:kontakt@bjerkholtstudio.no">kontakt@bjerkholtstudio.no</a></p>`;
 if(type==='help')html=`<h2>${t('help')}</h2><p>${t('helpIntro')}</p><p>${t('doubleTip')}</p><p>${t('colors')}</p><p>${t('gateTip')}</p><p>${t('frostTip')}</p><p>${t('threeColors')}</p><p>${t('hintNote')}</p>`;
 if(type==='pause')html=`<h2>${t('pause')}</h2><p style="text-align:center">${t('noPressure')}</p><button class="primary" data-action="close">${t('resume')}</button><div class="dialog-actions"><button data-action="restart">${t('restart')}</button><button data-action="home">${t('home')}</button></div>`;
 if(type==='result')html=`<div class="dialog-topbar"><button class="icon" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div><div class="solution-preview">${board(level,rot,false)}</div><div class="result-player" style="--avatar:${avatarColors[activeProfile.symbol]}">${avatarHTML(activeProfile)} ${escapeHtml(activeProfile.name)}</div><div class="result-level">${t('level')} ${level.id} · ${t('finished')}</div><h2>${level.id===chapterFor(level.id).end?t('chapterComplete',{name:t(chapterFor(level.id).key)}):t('solved')}</h2>${level.id===chapterFor(level.id).end?`<p>${t('chapterCompleteDesc',{name:t(chapterFor(level.id).key),n:chapterFor(level.id).end-chapterFor(level.id).start+1})}</p>`:''}<div class="result-stats"><div class="result-circle time-circle ${record.time?'new-record':''}"><span>${t('time')}</span><strong>${fmt(elapsed)}</strong></div><div class="result-circle moves-circle ${record.moves?'new-record':''}"><span>${t('moves')}</span><strong>${moves}</strong></div></div>${chapterReward?rewardView():''}${resultComparison()}<button class="text-button" data-action="scores">${t('levelRecords')}</button>${earnedHeadwear(data).includes(chapterFor(level.id).id)&&level.id===chapterFor(level.id).end?`<button class="chapter-share-button" data-action="chapterCard">${t('chapterCard')}</button>`:''}${level.id===levels.length?chapterPreview():''}<p class="notice">${practice?t('practiceResult'):assisted?t('assisted'):record.first?t('firstRecord'):[record.time?t('timeRecord'):'',record.moves?t('movesRecord'):''].filter(Boolean).join(' · ')}</p>${bankAward>0?`<p class="hint-budget">${t('bankEarned',{n:bankAward,b:data.hintBalance})}</p>`:''}${level.id<levels.length?`<div class="next-unlock"><span class="unlock-orb" aria-hidden="true">${String(level.id+1).padStart(2,'0')}</span><span>${t('nextUnlocked',{n:level.id+1})}</span></div>`:''}<button class="primary" data-action="${level.id<levels.length?'next':'home'}">${nextLabel()}</button><div class="dialog-actions"><button data-action="restart">${t('again')}</button><button data-action="levels">${t('levels')}</button></div>${level.id<levels.length?`<button class="result-home" data-action="home">${t('home')}</button>`:''}`;
 if(type==='result'&&level.id===chapterFor(level.id).end){html=chapterResultView(record);modal.className='result-dialog chapter-result-dialog';}
 if(type==='restartConfirm')html=`<h2>${t('restartConfirm')}</h2><p>${t('restartWarning')}</p><button class="primary" data-action="close">${t('resume')}</button><button class="menu-return" data-action="confirmRestart">${t('restart')}</button>`;
 if(['settings','help','about','players','scores','backup','newPlayer','editPlayer','chapterCard','purchase','reviewAccess'].includes(type))html=`<div class="menu-nav"><button class="icon" data-action="dialogBack" aria-label="${t('back')}">${icon('back')}</button><button class="icon" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div>`+html+(['newPlayer','editPlayer'].includes(type)?'':`<button class="menu-return" data-action="dialogBack">${t(dialogStack.length?'back':'close')}</button>`);const editing=['newPlayer','editPlayer'].includes(type);if(editing)modal.className+=' profile-editor-dialog';const oldScroll=modal.scrollTop||0;modal.innerHTML=html;if(editing)modal.scrollTop=oldScroll;if(!modal.open)modal.showModal();syncAmbience();}
function openChapterCard(){
 const chapter=screen==='levels'?chapters.find(c=>c.id===selectedChapter):chapterFor(level?.id||continueLevel());
 if(!earnedHeadwear(data).includes(chapter.id))return;
 const snapshot=chapterSummary(activeProfile,data,chapter);cardSnapshot=snapshot;cardReady=null;
 if(dialogType&&dialogType!=='chapterCard')dialogStack.push(dialogType);showDialog('chapterCard');const generation=++cardGeneration;
 drawChapterCard(snapshot).then(canvas=>{if(generation!==cardGeneration||dialogType!=='chapterCard')return;cardReady={canvas,dataUrl:exportChapterCard(canvas),name:`glimbraid-${chapter.id}.png`,snapshot};const preview=document.querySelector('#chapterCardPreview');if(preview)preview.innerHTML=`<img src="${cardReady.dataUrl}" alt="${escapeHtml(t('chapterComplete',{name:snapshot.chapterName})+'. '+snapshot.name)}">`;for(const a of ['shareChapterCard','saveChapterCard']){const b=document.querySelector(`[data-action="${a}"]`);if(b)b.disabled=false;}}).catch(error=>{if(generation===cardGeneration&&dialogType==='chapterCard'){const preview=document.querySelector('#chapterCardPreview');if(preview)preview.innerHTML=`<p>${t('cardError')}</p><p class="card-error-code">${t('cardErrorCode',{code:escapeHtml(/^CARD_[A-Z_]+$/.test(error?.code||'')?error.code:'CARD_DRAW')})}</p><button data-action="retryCard">${t('retryCard')}</button>`;}});
}
async function sendChapterCard(save=false){
 if(dialogType!=='chapterCard'||!cardReady||cardSending)return;cardSending=true;const prepared=cardReady;
 try{const result=await deliverCard(prepared,save);if(dialogType==='chapterCard'&&prepared===cardReady){const status=document.querySelector('#cardStatus');if(status)status.textContent=t(result==='cancelled'?'cardCancelled':result==='saved'?'cardSaved':'shareOpened');}}
 catch{if(dialogType==='chapterCard'&&prepared===cardReady){const status=document.querySelector('#cardStatus');if(status)status.textContent=t('cardError');}}finally{cardSending=false;}
}
function backupView(){return `<h2>${t('backup')}</h2><p>${t('backupNote')}</p><p>${t('lastBackup')}: ${data.lastBackup?escapeHtml(new Date(data.lastBackup).toLocaleString(data.lang)):t('neverBackup')}</p><button class="primary" data-action="exportBackup">${t('exportBackup')}</button><label class="profile-label" for="backupFile">${t('importBackup')}</label><input id="backupFile" type="file" accept=".json,application/json"><p id="backupStatus" role="status"></p>${pendingBackup?`<div class="backup-preview"><strong>${t('backupPreview',{n:pendingBackup.profiles.length})}</strong><p>${pendingBackup.profiles.map(p=>escapeHtml(p.name)).join(' · ')}</p><p>${t('replaceWarning')}</p><button data-action="restoreBackup">${t('restoreBackup')}</button></div>`:''}`;}
async function exportBackup(){
 persist();
 const exportingProfile=activeProfile;
 const backup={format:'sporlys-backup',version:1,createdAt:new Date().toISOString(),activeProfile:activeProfile.id,profiles};
 const content=JSON.stringify(backup,null,2),name=`glimbraid-sikkerhetskopi-${new Date().toISOString().slice(0,10)}.json`;
 if(globalThis.SporlysNative?.saveBackup){
  const button=document.querySelector('[data-action="exportBackup"]');if(button?.disabled)return;if(button)button.disabled=true;
  try{
   const result=await globalThis.SporlysNative.saveBackup({content,name});
   if(result.saved){
    const now=new Date().toISOString();exportingProfile.data.lastBackup=now;
    if(activeProfile.id===exportingProfile.id)data.lastBackup=now;
    persist();if(dialogType==='backup')showDialog('backup');
   }
   const status=document.querySelector('#backupStatus');if(status)status.textContent=t(result.saved?'backupNativeSaved':'backupCancelled');
  }catch{const status=document.querySelector('#backupStatus');if(status)status.textContent=t('backupNativeError');}
  finally{if(button)button.disabled=false;}return;
 }
 const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));
 const a=document.createElement('a');a.href=url;a.download=name;a.click();data.lastBackup=new Date().toISOString();persist();
 if(dialogType==='backup')showDialog('backup');const status=document.querySelector('#backupStatus');if(status)status.textContent=t('backupExported');setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function readBackup(file){pendingBackup=null;if(!file)return;try{if(file.size>2*1024*1024)throw Error('Too large');const candidate=validateBackup(JSON.parse(await file.text()),levels.length);if(dialogType!=='backup')return;pendingBackup=candidate;showDialog('backup');}catch{if(dialogType==='backup'){showDialog('backup');const status=document.querySelector('#backupStatus');if(status)status.textContent=t('backupError');}}}
function restoreBackup(){if(!pendingBackup||dialogType!=='backup')return;const candidate=pendingBackup;candidate.profiles.forEach(p=>initHints(p.data));const p=candidate.profiles.find(p=>p.id===candidate.activeProfile);try{localStorage.setItem(KEY,JSON.stringify({...p.data,version:2,profiles:candidate.profiles,activeProfile:p.id}));}catch{const status=document.querySelector('#backupStatus');if(status)status.textContent=t('backupSaveError');return;}profiles=candidate.profiles;activeProfile=p;data={...p.data};initHints(data);pendingBackup=null;screen='home';level=undefined;started=false;won=false;paused=false;lastTick=0;pendingHint=null;chapterReward=null;t=translator(data.lang);closeDialog();toast=t('backupRestored');render();}
function playersView(){return `<div class="profile-hero"><span class="profile-emblem" style="--avatar:${avatarColors[activeProfile.symbol]}">${avatarHTML(activeProfile)}</span><h2>${t('players')}</h2></div><div class="player-list">${profiles.map(p=>`<div class="player-entry"><button data-player="${escapeHtml(p.id)}" class="player-row ${p.id===activeProfile.id?'selected':''}" aria-pressed="${p.id===activeProfile.id}"><span class="avatar" style="--avatar:${avatarColors[p.symbol]}">${avatarHTML(p)}</span><span><strong>${escapeHtml(p.name)}</strong><small>${t('progressShort',{a:p.id===activeProfile.id?data.completed.length:p.data.completed.length,b:levels.length})}</small></span></button><button class="player-delete" data-delete-player="${escapeHtml(p.id)}" aria-label="${escapeHtml(t('deletePlayerTitle',{name:p.name}))}">${t('deletePlayer')}</button></div>`).join('')}</div>${profiles.length<6?`<button class="primary" data-action="newPlayer">${t('newPlayer')}</button>`:''}<button class="menu-return" data-action="editPlayer">${t('editPlayer')}</button><p class="muted">${t('profilesNote')}</p>`;}
function profileForm(add){
 const d=profileDraft||{name:'',symbol:0,hat:'none'},progress=add?{completed:[]}:data;
 const cards=characters.map((character,i)=>{const users=profiles.filter(p=>p.symbol===i&&(add||p.id!==activeProfile.id)).map(p=>p.name);const using=users.length?t('chosenBy',{name:users.join(', ')}):t('chooseThis');return `<button data-avatar="${i}" class="character-choice ${d.symbol===i?'selected':''}" aria-pressed="${d.symbol===i}" aria-label="${escapeHtml(t('character'+i)+'. '+using)}"><span class="choice-art">${avatarHTML({symbol:i,hat:'none'})}</span><strong>${t('character'+i)}</strong><small title="${escapeHtml(using)}">${escapeHtml(using)}</small></button>`;}).join('');
 return `<section class="profile-editor"><div class="profile-summary"><div class="profile-preview">${avatarHTML(d)}</div><div><h2>${t(add?'newPlayer':'editPlayer')}</h2><label for="playerName">${t('playerName')}</label><input id="playerName" maxlength="24" value="${escapeHtml(d.name)}" autocomplete="off"></div></div><div class="picker-heading"><h3>${t('chooseCharacter')}</h3><span>${t('sharedFigures')}</span></div><div class="character-picker">${cards}</div><div class="picker-heading"><h3>${t('headwear')}</h3><span>${t('earnedCount',{n:earnedHeadwear(progress).length,total:headwear.length-1})}</span></div><div class="headwear-picker" role="group" aria-label="${t('headwear')}">${headwear.map(h=>{const available=canWear(progress,h);return `<button data-hat="${h}" class="headwear-choice ${d.hat===h?'selected':''}" aria-pressed="${d.hat===h}" ${available?'':'disabled'} aria-label="${t('hat_'+h)}${available?'':'. '+t('hatLocked',{name:t(chapters.find(c=>c.id===h).key)})}">${h==='none'?`<span class="bare-head">${icon('close')}</span>`:`<img src="characters/hat-${h}.png" alt="">`}<span>${t('hat_'+h)}</span>${available?'':`<small>${t('hatLocked',{name:t(chapters.find(c=>c.id===h).key)})}</small>`}</button>`;}).join('')}</div><p class="reward-note">${t('rewardNote')}</p><p id="profileError" role="status"></p><button class="primary profile-save" data-action="saveProfile">${t(add?'createPlayer':'savePlayer')}</button></section>`;
}
function nextLabel(){if(level.id===12&&!purchases.state.owned)return t('fullGameTitle');const next=chapters.find(c=>c.start===level.id+1);return next?t('startChapter',{name:t(next.key)}):t(level.id<levels.length?'next':'home');}
function chapterResultView(record){
 const chapter=chapterFor(level.id),count=chapter.end-chapter.start+1,hasNext=level.id<levels.length;
 const message=practice?t('practiceResult'):assisted?t('assisted'):record.first?t('firstRecord'):[record.time?t('timeRecord'):'',record.moves?t('movesRecord'):''].filter(Boolean).join(' · ');
 const reward=chapterReward?`<section class="chapter-prize" role="status"><strong>${t('rewardUnlocked')}</strong><span>${t('hat_'+chapterReward)}</span><div class="reward-actions"><button data-action="equipReward" ${activeProfile.hat===chapterReward?'disabled':''}>${t(activeProfile.hat===chapterReward?'wearingReward':'wearReward')}</button><button class="text-button" data-action="dismissReward">${t('chooseLater')}</button></div></section>`:'';
 return `<div class="dialog-topbar"><button class="icon" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div><div class="chapter-finale"><div class="chapter-finale-avatar">${avatarHTML(activeProfile,chapterReward||activeProfile.hat)}</div><h2>${t('chapterComplete',{name:t(chapter.key)})}</h2><p class="chapter-finale-player">${escapeHtml(activeProfile.name)} · ${count}/${count} ${t('cardLevels').toLowerCase()}</p></div>${reward}<button class="primary chapter-next" data-action="${hasNext?'next':'home'}">${nextLabel()}</button><button class="chapter-share-button" data-action="chapterCard">${t('chapterCard')}</button>${bankAward>0?`<p class="hint-budget">${t('bankEarned',{n:bankAward,b:data.hintBalance})}</p>`:''}<details class="chapter-result-details"><summary>${t('levelResult',{n:level.id})}</summary><div class="solution-preview">${board(level,rot,false)}</div><div class="result-stats"><div class="result-circle time-circle ${record.time?'new-record':''}"><span>${t('time')}</span><strong>${fmt(elapsed)}</strong></div><div class="result-circle moves-circle ${record.moves?'new-record':''}"><span>${t('moves')}</span><strong>${moves}</strong></div></div>${resultComparison()}<button class="text-button" data-action="scores">${t('levelRecords')}</button><p class="notice">${message}</p>${hasNext?`<p class="next-unlock">${t('nextUnlocked',{n:level.id+1})}</p>`:''}<div class="dialog-actions"><button data-action="restart">${t('again')}</button><button data-action="levels">${t('levels')}</button></div>${hasNext?`<button class="result-home" data-action="home">${t('home')}</button>`:''}</details>${!hasNext?chapterPreview():''}`;
}

function rewardView(){return `<section class="chapter-reward" role="status"><div class="reward-avatar">${avatarHTML(activeProfile,chapterReward)}</div><div><strong>${t('rewardUnlocked')}</strong><p>${t('hat_'+chapterReward)}</p></div><div class="reward-actions"><button data-action="equipReward" ${activeProfile.hat===chapterReward?'disabled':''}>${t(activeProfile.hat===chapterReward?'wearingReward':'wearReward')}</button><button class="text-button" data-action="dismissReward">${t('chooseLater')}</button></div></section>`;}

function resultComparison(){if(!previousBest)return '';return `<div class="record-comparison"><p>${t('previousBest')}: ${fmtPrecise(previousBest.time)} · ${previousBest.moves} ${t('moves').toLowerCase()}</p>${!assisted&&resultRecord.time?`<strong>${t('timeBetter',{n:numberText(data.lang,(previousBest.time-elapsed)/1000,2)})}</strong>`:''}${!assisted&&resultRecord.moves?`<strong>${t('movesBetter',{n:previousBest.moves-moves})}</strong>`:''}</div>`;}
const fmtPrecise=ms=>`${fmt(ms)}.${String(Math.floor(ms%1000/10)).padStart(2,'0')}`;
function levelGrid(c){return `<div class="compact-levels">${levels.filter(l=>l.id>=c.start&&l.id<=c.end).map(l=>`<button data-level="${l.id}" ${!levelUnlocked(l.id)?'disabled':''} class="${data.completed.includes(l.id)?'completed':''}" aria-label="${t('level')} ${l.id}"><strong>${l.id}</strong><small>${t(data.completed.includes(l.id)?'finished':l.id===continueLevel()?'continue':'levelReady')}</small></button>`).join('')}</div>`;}
function savePlayer(add){const name=document.querySelector('#playerName')?.value.trim().slice(0,24);if(!name||profiles.some(p=>p.id!==(!add?activeProfile.id:'')&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase())){const error=document.querySelector('#profileError');if(error)error.textContent=t('nameError');return;}if(add){if(profiles.length>=6)return;persist();const p={id:globalThis.crypto?.randomUUID?.()||`player-${Date.now()}-${profiles.length}`,name,autoName:false,symbol:profileDraft?.symbol??activeProfile.symbol,hat:'none',data:{version:1,lang:data.lang,sound:data.sound,ambience:data.ambience,haptics:data.haptics,showTime:data.showTime,records:{},completed:[],last:1}};profiles.push(p);switchPlayer(p.id);}else{if(name!==activeProfile.name)activeProfile.autoName=false;activeProfile.name=name;activeProfile.symbol=profileDraft?.symbol??activeProfile.symbol;activeProfile.hat=canWear(data,profileDraft?.hat)?profileDraft.hat:'none';persist();profileDraft=null;dialogStack=dialogStack.filter(x=>x!=='players');render();showDialog('players');}}
function switchPlayer(id){const p=profiles.find(p=>p.id===id);if(!p)return;tick();persist();activeProfile=p;data={...p.data};initHints(data);t=translator(data.lang);screen='home';level=undefined;started=false;won=false;paused=false;lastTick=0;pendingHint=null;chapterReward=null;closeDialog();persist();render();}
function deletePlayer(){
 const id=pendingDelete;if(!id||!profiles.some(p=>p.id===id))return;
 tick();persist();let next=profiles.filter(p=>p.id!==id);const deletingActive=activeProfile.id===id;
 if(!next.length){const fresh={version:1,lang:data.lang,sound:data.sound,ambience:data.ambience,haptics:data.haptics,showTime:data.showTime,records:{},completed:[],last:1,hintBalance:0,hintBaseUsed:{}};next=[{id:globalThis.crypto?.randomUUID?.()||`player-${Date.now()}`,name:translator(data.lang)('defaultPlayer',{n:1}),autoName:true,symbol:0,hat:'none',data:fresh}];}
 const active=deletingActive?next[0]:next.find(p=>p.id===activeProfile.id);
 try{localStorage.setItem(KEY,JSON.stringify({...active.data,version:2,profiles:next,activeProfile:active.id}));}catch{storageOK=false;pendingDelete=null;showDialog('players');toast=t('deleteFailed');render();return;}
 profiles=next;activeProfile=active;data={...active.data};initHints(data);t=translator(data.lang);pendingDelete=null;profileDraft=null;dialogStack=[];cardGeneration++;cardReady=null;cardSnapshot=null;
 screen='home';level=undefined;started=false;won=false;paused=false;lastTick=0;pendingHint=null;chapterReward=null;closeDialog();render();showDialog('players');
}
function scoresView(){
 const chapter=chapters.find(c=>c.id===scoreChapter)||chapters[0];
 const players=profiles.map(p=>({...p,data:p.id===activeProfile.id?data:p.data}));
 const rows=scoreRows(players,{levelId:scoreLevel,chapter:scoreScope==='chapter'?chapter:null,metric:scoreMetric});
 const selection=scoreScope==='chapter'?`<label class="setting">${t('scoreCategory')}<select id="scoreChapter">${chapters.map(c=>`<option value="${c.id}" ${c.id===chapter.id?'selected':''}>${t(c.key)}</option>`).join('')}</select></label><p class="score-explanation">${t('scoreChapterNote')}</p>`:`<label class="setting">${t('level')}<select id="scoreLevel">${levels.map(l=>`<option value="${l.id}" ${l.id===scoreLevel?'selected':''}>${t(chapterFor(l.id).key)} · ${l.id}</option>`).join('')}</select></label>`;
 return `<h2>${t('scores')}</h2><p>${t('scoresNote')}</p><div class="chapter-tabs score-scope">${['level','chapter'].map(scope=>`<button data-score-scope="${scope}" class="${scoreScope===scope?'selected':''}" aria-pressed="${scoreScope===scope}">${t(scope==='level'?'level':'scoreCategory')}</button>`).join('')}</div>${selection}<div class="chapter-tabs score-metrics">${['time','moves'].map(m=>`<button data-metric="${m}" class="${scoreMetric===m?'selected':''}" aria-pressed="${scoreMetric===m}">${t(scoreScope==='chapter'?(m==='time'?'scoreTotalTime':'scoreTotalMoves'):(m==='time'?'fastest':'fewest'))}</button>`).join('')}</div><ol class="score-list">${rows.map(p=>`<li class="${p.id===activeProfile.id?'own-score ':''}${p.value===null?'score-unranked':''}"><span class="rank">${p.rank??'—'}</span><span class="score-player">${avatarHTML(p)} <span>${escapeHtml(p.name)}</span></span>${p.value===null?`<small class="score-pending">${scoreScope==='chapter'?t('scoreMissing',{n:p.count,total:p.total}):t('scoreNoRecord')}</small>`:`<strong>${scoreMetric==='time'?fmtPrecise(p.value):numberText(data.lang,p.value)}</strong>`}</li>`).join('')}</ol>`;
}

function useHint(){
 if(screen!=='play'||won||paused)return;
 if(pendingHint){const {tile:i,rotation}=pendingHint,before=evaluate(level,rot),turns=(rotation-rot[i]+4)%4;if(level.frozen===i&&!before.open){pendingHint=null;persist();render();return;}begin();history.push([...rot]);rot[i]=rotation;pendingHint=null;moves++;render();checkWin();animateMove(before,i,turns);return;}
 if(!practice&&remainingHints(data,level.id,hintsUsed)===0){showDialog('practice');return;}
 const suggestion=nextHint(level,rot);if(!suggestion)return;
 begin();pendingHint=suggestion;assisted=true;if(!practice){spendHint(data,level.id,hintsUsed);hintsUsed++;}persist();render();
}
function action(name){if(name==='reviewAccess'){dialogStack.push(dialogType);showDialog('reviewAccess');return;}if(name==='activateReview'){void activateReview();return;}if(name==='endReview'){persist();try{reviewAccess.end();globalThis.location.reload();}catch{document.querySelector('#reviewStatus').textContent=t('reviewError');}return;}if(name==='freeGame'){screen='levels';selectedChapter='night';closeDialog();return;}if(name==='purchase'){showDialog('purchase');return;}if(name==='buyGame'){purchases.buy();return;}if(name==='restorePurchases'){purchases.restore();return;}if(name==='cancelDeletePlayer'){pendingDelete=null;showDialog('players');return;}if(name==='confirmDeletePlayer'&&dialogType==='deletePlayerConfirm'){deletePlayer();return;}if(name==='chapterCard'||name==='retryCard'){openChapterCard();return;}if(name==='shareChapterCard'){sendChapterCard();return;}if(name==='saveChapterCard'){sendChapterCard(true);return;}if(name==='equipReward'&&chapterReward&&canWear(data,chapterReward)){activeProfile.hat=chapterReward;persist();render();showDialog('result');return;}if(name==='dismissReward'&&chapterReward){chapterReward=null;showDialog('result');return;}if(name==='dialogBack'){profileDraft=null;const parent=dialogStack.pop();if(parent)showDialog(parent);else closeDialog();return;}if(name==='newPlayer'||name==='editPlayer'){profileDraft={name:name==='newPlayer'?'':activeProfile.name,symbol:name==='newPlayer'?0:activeProfile.symbol,hat:name==='newPlayer'?'none':activeProfile.hat||'none'};dialogStack.push(dialogType);showDialog(name);return;}if(name==='saveProfile'){savePlayer(dialogType==='newPlayer');return;}if(name==='backup'){if(dialogType&&dialogType!=='backup')dialogStack.push(dialogType);pendingBackup=null;showDialog('backup');return;}if(name==='exportBackup'){exportBackup();return;}if(name==='restoreBackup'){restoreBackup();return;}if(name==='players'||name==='scores'){if(dialogType&&dialogType!==name)dialogStack.push(dialogType);scoreLevel=level?.id||continueLevel();scoreChapter=chapterFor(scoreLevel).id;showDialog(name);return;}if(name==='enterPractice'&&dialogType==='practice'&&screen==='play'&&!won){practice=true;assisted=true;closeDialog();return;}if(name==='result'&&won&&screen==='play'){showDialog('result',resultRecord);return;}if(name==='close'){closeDialog();return;}if(name==='home'||name==='levels'){tick();persist();screen=name;if(name==='levels')selectedChapter=chapterFor(continueLevel()).id;closeDialog();render();return;}if(name==='start'){start(continueLevel(),true);return;}if(name==='settings'||name==='help'||name==='about'){showDialog(name);return;}if(name==='pause'){pause();return;}if(name==='restart'){if(screen==='play'&&!won&&(moves>0||pendingHint||practice))showDialog('restartConfirm');else start(level.id);return;}if(name==='confirmRestart'&&dialogType==='restartConfirm'&&screen==='play'&&!won){start(level.id);return;}if(name==='next'){start(level.id+1);return;}if(name==='undo'&&history.length&&!won){pendingHint=null;begin();rot=history.pop();moves++;sound();persist();render();return;}if(name==='hint'){useHint();return;}}
document.addEventListener('click',e=>{soundscape.unlock(data.sound||data.ambience);const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){levelView=b.dataset.view==='grid'?'grid':'journey';render();return;}if(b.dataset.hat!==undefined){const h=b.dataset.hat;if(profileDraft&&headwear.includes(h)&&canWear(dialogType==='newPlayer'?{completed:[]}:data,h)){profileDraft.name=document.querySelector('#playerName')?.value||'';profileDraft.hat=h;showDialog(dialogType);}return;}if(b.dataset.avatar!==undefined){const i=Number(b.dataset.avatar);if(profileDraft&&Number.isInteger(i)&&i>=0&&i<6){profileDraft.name=document.querySelector('#playerName')?.value||'';profileDraft.symbol=i;showDialog(dialogType);}return;}if(b.dataset.deletePlayer){pendingDelete=b.dataset.deletePlayer;showDialog('deletePlayerConfirm');return;}if(b.dataset.player){switchPlayer(b.dataset.player);return;}if(b.dataset.scoreScope){scoreScope=b.dataset.scoreScope==='chapter'?'chapter':'level';showDialog('scores');return;}if(b.dataset.metric){scoreMetric=b.dataset.metric;showDialog('scores');return;}if(b.dataset.chapter){const chapter=chapters.find(c=>c.id===b.dataset.chapter);if(!chapter)return;if(!purchases.canPlay(chapter.start)){showDialog('purchase');return;}if(!levelUnlocked(chapter.start))return;selectedChapter=chapter.id;screen='levels';render();}else if(b.dataset.rotate!==undefined)rotate(Number(b.dataset.rotate));else if(b.dataset.level)start(Number(b.dataset.level),true);else if(b.dataset.action)action(b.dataset.action);});
modal.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
modal.addEventListener('change',e=>{if(e.target.id==='backupFile'){readBackup(e.target.files?.[0]);return;}if(e.target.id==='scoreChapter'&&chapters.some(c=>c.id===e.target.value)){scoreChapter=e.target.value;showDialog('scores');return;}if(e.target.id==='scoreLevel'){scoreLevel=Number(e.target.value);showDialog('scores');return;}if(e.target.id==='language'&&supportedLanguages.includes(e.target.value)){data.lang=e.target.value;t=translator(data.lang);persist();render();showDialog('settings');}if(['sound','showTime','ambience','haptics'].includes(e.target.id)){data[e.target.id]=e.target.checked;soundscape.unlock(data.sound||data.ambience);persist();render();}});
persist();render();
purchases.subscribe(state=>{
 if(dialogType==='purchase'){
  if(state.owned&&wantedPaidLevel){const id=wantedPaidLevel;wantedPaidLevel=null;start(id,true);}
  else showDialog('purchase');
 }else if(!reviewAccess.active&&!state.owned&&screen==='play'&&level.id>12&&!won){persist();wantedPaidLevel=level.id;showDialog('purchase');}
 else if(screen==='levels')render();
});
void purchases.initialize();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_sporlys_game',description:'Read the current Glimbraid level and progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({screen,level:level?.id,moves,rotations:rot,completed:data.completed})});document.modelContext.registerTool({name:'rotate_sporlys_tile',description:'Rotate one tile in the active Glimbraid level clockwise.',inputSchema:{type:'object',properties:{tile:{type:'integer',minimum:0}},required:['tile'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.tile))throw new Error('Integer tile required');rotate(input.tile);return {moves,solved:won};}});}catch{}}

function purchaseView(){if(reviewAccess.active)return reviewView();const state=purchases.state;return `<section class="purchase-panel"><h2>${t(state.owned?'fullGameActive':'fullGameTitle')}</h2><p>${t('fullGameBody')}</p><p class="muted">${t('purchaseShared')}</p>${state.owned?'':`<button class="primary" data-action="buyGame" ${!state.available||state.busy||state.status==='storePending'?'disabled':''}>${state.price?escapeHtml(t('unlockGame',{price:state.price})):t('unlockGameNoPrice')}</button><p class="purchase-note">${t('purchaseOnce')}</p>`}<button class="menu-return" data-action="restorePurchases" ${state.busy?'disabled':''}>${t('restorePurchases')}</button><p role="status" class="purchase-status">${state.status?t(state.status):''}</p><button class="text-button" data-action="${state.owned?'close':'freeGame'}">${t(state.owned?'close':'purchaseContinueFree')}</button></section>`;}

function reviewView(){return `<section class="review-panel"><h2>${t('reviewTitle')}</h2><p>${t('reviewExplain')}</p>${reviewAccess.active?`<p>${t('reviewActive')}</p><button class="primary" data-action="endReview">${t('reviewEnd')}</button>`:`<label for="reviewCode">${t('reviewCode')}</label><input id="reviewCode" type="password" autocomplete="off" autocapitalize="characters" spellcheck="false"><button class="primary" data-action="activateReview">${t('reviewActivate')}</button>`}<p id="reviewStatus" role="status"></p></section>`;}
async function activateReview(){const button=document.querySelector('[data-action="activateReview"]');if(!button||button.disabled)return;button.disabled=true;try{if(await reviewAccess.activate(document.querySelector('#reviewCode').value)){persist();globalThis.location.reload();return;}document.querySelector('#reviewStatus').textContent=t('reviewInvalid');}catch{document.querySelector('#reviewStatus').textContent=t('reviewError');}button.disabled=false;}
